#!/usr/bin/env python3
"""Telnet front-end for a QEMU serial unix socket.

Listens on 127.0.0.1:<port>, speaks the same minimal telnet option set QEMU's
own telnet chardev does (char-at-a-time, remote echo), and forwards bytes to /
from the guest serial line.  On each new client connection it nudges the guest
with a CR so a fresh `login:` prompt is printed immediately.
All guest output is also appended to a log file for readiness checks.
"""
import os
import socket
import sys
import threading
import time

SOCK = sys.argv[1] if len(sys.argv) > 1 else "/tmp/alpine-serial.sock"
PORT = int(sys.argv[2]) if len(sys.argv) > 2 else 6665
LOG = sys.argv[3] if len(sys.argv) > 3 else "/tmp/alpine-serial.log"

IAC, DONT, DO, WONT, WILL, SB, SE = 255, 254, 253, 252, 251, 250, 240
OPT_BINARY, OPT_ECHO, OPT_SGA = 0, 1, 3
HELLO = bytes([
    IAC, WILL, OPT_ECHO,
    IAC, WILL, OPT_SGA,
    IAC, WILL, OPT_BINARY,
    IAC, DO, OPT_BINARY,
])

lock = threading.Lock()
client = {"sock": None}
logf = open(LOG, "ab", buffering=0)


def connect_guest():
    while True:
        try:
            s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
            s.connect(SOCK)
            return s
        except OSError:
            time.sleep(0.25)


guest = connect_guest()


def guest_reader():
    while True:
        try:
            data = guest.recv(4096)
        except OSError:
            data = b""
        if not data:
            time.sleep(0.2)
            continue
        logf.write(data)
        with lock:
            c = client["sock"]
            if c is not None:
                try:
                    c.sendall(data.replace(bytes([IAC]), bytes([IAC, IAC])))
                except OSError:
                    pass


def strip_telnet(buf, state):
    """Remove telnet control sequences; state carries partial sequences."""
    out = bytearray()
    for b in buf:
        st = state["st"]
        if st == "data":
            if b == IAC:
                state["st"] = "iac"
            else:
                out.append(b)
        elif st == "iac":
            if b == IAC:
                out.append(IAC)
                state["st"] = "data"
            elif b in (DO, DONT, WILL, WONT):
                state["st"] = "opt"
            elif b == SB:
                state["st"] = "sb"
            else:
                state["st"] = "data"
        elif st == "opt":
            state["st"] = "data"
        elif st == "sb":
            if b == IAC:
                state["st"] = "sbiac"
        elif st == "sbiac":
            state["st"] = "data" if b == SE else "sb"
    return bytes(out)


def serve():
    srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    srv.bind(("127.0.0.1", PORT))
    srv.listen(1)
    while True:
        conn, _ = srv.accept()
        conn.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        with lock:
            old = client["sock"]
            client["sock"] = conn
        if old is not None:
            try:
                old.close()
            except OSError:
                pass
        try:
            conn.sendall(HELLO)
            guest.sendall(b"\r")  # provoke a fresh login prompt
        except OSError:
            pass
        state = {"st": "data"}
        try:
            while True:
                data = conn.recv(1024)
                if not data:
                    break
                payload = strip_telnet(data, state)
                if payload:
                    guest.sendall(payload)
        except OSError:
            pass
        finally:
            with lock:
                if client["sock"] is conn:
                    client["sock"] = None
            try:
                conn.close()
            except OSError:
                pass


threading.Thread(target=guest_reader, daemon=True).start()
serve()

