import subprocess,time,os,pty,select
def session(cmds):
    m,s=pty.openpty()
    p=subprocess.Popen(['telnet','127.0.0.1','6665'],stdin=s,stdout=s,stderr=s)
    os.close(s); out=b''
    t=time.time()
    for c in cmds:
        # wait a bit, read
        deadline=time.time()+20
        while time.time()<deadline:
            r,_,_=select.select([m],[],[],1)
            if r:
                try: out+=os.read(m,4096)
                except OSError: break
            else: break
        os.write(m,c)
    time.sleep(5)
    while select.select([m],[],[],1)[0]:
        try: out+=os.read(m,4096)
        except OSError: break
    p.kill(); os.close(m)
    return out.decode('latin1')
o=session([b'root\r',b'echo HELLO-$(hostname)-OK\r',b'\x1d'])
print(o[-1200:])
EOF
